 LinearLayout card(LinearLayout parent){LinearLayout c=column();c.setPadding(dp(12),dp(10),dp(12),dp(10));c.setBackground(MobileUi.shape(this,MobileUi.surface(this),18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(8));parent.addView(c,lp);return c;}
